    {
      "keystrokes": "cat > /tmp/decode.c << 'EOF'
#include <stdio.h>
int main(){
 unsigned u[]={0x00020001,0x40800000,0x3883126f,0x38d1b717,0x3e4ccccd,0x3f666666,0x3ecccccd,0xbfc00000,0x3f4ccccd,0x4b000000,0x437ffd71,0xbf800000,0x42c80000,0x44160000,0x4415c000,0x4447c000,0x402aaaab,0x3faaaaab,0x00000000,0x3f800000};
 for(int i=0;i<20;i++){float f=*(float*)&u[i];printf("0x%08x = %.10g\n",u[i],f);}
 return 0;
}
EOF
gcc -o /tmp/decode /tmp/decode.c && /tmp/decode
",
      "duration": 0.1
    },
